void point_swap(void **p, void **q) {
    void *temp = *p;
    *p = *q;
    *q = temp;
}

void swap(int *p, int *q) {
    int temp = *p;
    *p = *q;
    *q = temp;
}

void row_reverse(void **A, int n, int *SIZE) {
    int row1, row2;
    for (row1=0, row2=n-1; row1<row2; row1++, row2--) {
        point_swap(A + row1, A + row2);
        swap(SIZE + row1, SIZE + row2);
    }
}
```

